void sensor_task(void *arg) {
    char json[2048];
    while (1) {
        build_payload(json, sizeof(json));
        mqtt_publish("sensors/room1", json);
        vTaskDelay(pdMS_TO_TICKS(5000));
    }
}

void app_main(void) {
    xTaskCreate(sensor_task, "sensor_task", 1024, NULL, 5, NULL);
}
